############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PCCmacros.pl", "contextForm.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
($m,$h,$k) = random_subset(3,2..9); $k = -$k; $m = list_random($m,-$m); Context()->noreduce('(-x)-y','(-x)+y'); $f = Formula("$m(x-$h)+$k")->reduce; Context("Point"); Context()->parens->set("[" => {type => "Interval", close => "]"}); Context()->parens->set("{" => {type => "Set", close => "}"}); Context()->parens->set("<" => {type => "Vector", close => ">"}); $p = Point("($h,$k)");
############################# # Exercise Group Introduction #############################
BEGIN_PGML A line's equation is given in point-slope form. Identify the slope and the point on the line that is being singled out.
END_PGML
###### # Body ######
BEGIN_PGML [`y=[$f]`]
[@KeyboardInstructions('Enter the slope here.')@]**
[_]{$m}{5}
[@KeyboardInstructions('Enter the point here.')@]**
[_]{$p}{5}
END_PGML
############# # End Problem #############
